; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: zxndotl (ZX Spectrum Next - a dot command, Large Model (32K at #8000 + banks, BASIC's screen)), starts in normal mode
; ============================================================

			OUTPUT "VBTEST3.DOT"		; the dot command (C:/DOT/VBTEST3.DOT: .vbtest3 at the BASIC prompt)
; ZX Spectrum Next - a dot command, Large Model (32K at #8000 + banks, BASIC's screen): NTC_ZXNDOT defined, and NTC_ZXNDOTL (the Large Model: the program from #8000, the Memory class's banks from NextZXOS's allocator - asm/ntc_lib_dot.asm)
			DEFINE NTC_ZXNDOT
			DEFINE NTC_ZXNDOTL
			org #2000

; ============================================================
; Platform start code (the platform's ntc_plat_romhead) - at the org, on to ntc_start
; ============================================================
; ------------------------------------------------------------
; The entry (the compiler puts this section first, at #2000) and the
; BASIC-side machinery: everything the ROM calls need, in one place, so
; that the Large Model (zxndotl) - which runs the program from #8000 in its
; own pages and keeps only this 8K in common with BASIC's memory - has it
; here too. Self-contained: no label from another section is named.
; ------------------------------------------------------------
dot_entry:
			di
			ld (dot_bsp), sp		; BASIC's stack: the ROM calls run on it, End returns on it
			ld (dot_hl), hl			; the arguments (0: none)
			ld (dot_bc), bc
			ld a, i
			ld (dot_iold), a		; BASIC's I (put back at the end)
			ld sp, dot_tstack		; a stack of our own for the rest of the entry
			call dot_cmdsave		; the arguments into ntc_cmdbuf before anything moves them
	IFDEF NTC_ZXNDOTL
			call dotl_setup			; the Large Model: its pages, the program read from this file
	ENDIF
			ld hl, dot_chan			; the upper screen is the channel printed to
			call dot_os
			ld a, dot_ivec >> 8		; IM 2, our handler (dot_irq) from here on, except inside dot_os
			ld i, a
			im 2
			jp ntc_start

; dot_cmdsave - (dot_hl) = the arguments: into ntc_cmdbuf, 0 ended, up to 127
; characters, up to #0D, ':' outside double quotes, or 0; leading spaces left out
dot_cmdsave:
			ld hl, (dot_hl)
			ld de, ntc_cmdbuf
			ld a, h
			or l
			jr z, dot_cs_end
			ld b, 127
			ld c, 0					; C = 1 inside quotes
dot_cs_sp:
			ld a, (hl)
			cp ' '
			jr nz, dot_cs_lp
			inc hl
			jr dot_cs_sp
dot_cs_lp:
			ld a, (hl)
			or a
			jr z, dot_cs_end
			cp #0D
			jr z, dot_cs_end
			cp '"'
			jr nz, dot_cs_nq
			ld a, c
			xor 1
			ld c, a
			ld a, '"'
dot_cs_nq:
			cp ':'
			jr nz, dot_cs_st
			bit 0, c
			jr z, dot_cs_end		; a ':' outside quotes ends the line
dot_cs_st:
			ld (de), a
			inc hl
			inc de
			djnz dot_cs_lp
dot_cs_end:
			xor a
			ld (de), a
			ret

; dot_os - HL = a routine (in this 8K) to run on BASIC's side: BASIC's stack,
; IY = ERR_NR (the ROM's), interrupts on (the ROM's keyboard scan, "scroll?"),
; and - the Large Model - BASIC's memory in slots 2-7. Back with interrupts
; off, our stack (SP as it was) and our memory; A, BC, DE, HL as the routine
; left them, IX kept. Call it on the real stack, never with SP in the thread
dot_os:
			ld (dot_osp), sp
			ld (dot_oix), ix
	IFDEF NTC_ZXNDOTL
			ld sp, dot_xstack		; (the swap's calls: never on the program's stack, which is in a slot being swapped)
			push hl
			call dotl_bside			; slots 2-7 = BASIC's (ours noted)
			pop hl
	ENDIF
			ld sp, (dot_bsp)
			ld iy, #5C3A
			im 1					; the ROM's handler while the ROM runs
			ex de, hl
			ld hl, (#5C78)			; FRAMES now: its advance during the call is added to dot_frames
			ld (dot_fr0), hl
			ex de, hl
			ld de, dot_os_back
			push de
			ei
			jp (hl)
dot_os_back:
			di
			push af					; (the routine's result: A and the flags - dotl_alloc's carry)
			push hl
			push de
			ld hl, (#5C78)
			ld de, (dot_fr0)
			or a
			sbc hl, de
			ld de, (dot_frames)
			add hl, de
			ld (dot_frames), hl
			pop de
			pop hl
			pop af
	IFDEF NTC_ZXNDOTL
			ld sp, dot_xstack
			push af
			push hl
			call dotl_oside			; slots 2-7 = ours again
			pop hl
			pop af
	ENDIF
			im 2
			ld sp, (dot_osp)
			ld ix, (dot_oix)
			ret

; ---- the BASIC-side routines (reached through dot_os only)
; dot_chan - the upper screen, channel 2, is the channel rst #10 prints to
dot_chan:
			ld a, 2
			rst #18
			dw #1601				; CHAN-OPEN
			ret
; dot_putc - (dot_ch) printed
dot_putc:
			ld a, (dot_ch)
			rst #10
			ret
; dot_cls - the ROM's CLS, then the channel again (CLS leaves the lower screen's)
dot_cls:
			rst #18
			dw #0D6B				; CLS
			jr dot_chan
; dot_at - AT (dot_row), (dot_col): the ROM's control code 22
dot_at:
			ld a, 22
			rst #10
			ld a, (dot_row)
			rst #10
			ld a, (dot_col)
			rst #10
			ret
; dot_wait - a frame: until the ROM's interrupt moves FRAMES on (not halt: a program
; that stops on halt can't be stepped by every harness - and the ROM's handler runs
; the same either way)
dot_wait:
			ld hl, #5C78			; FRAMES
			ld a, (hl)
dot_wt_lp:
			cp (hl)
			jr z, dot_wt_lp
			ret
; dot_kread - a frame's wait for the ROM's keyboard scan, then A = the new key
; (LAST_K, the FLAGS bit cleared) or 0
dot_kread:
			call dot_wait
			ld a, (#5C3B)			; FLAGS: bit 5 = a new key in LAST_K
			bit 5, a
			jr z, dot_kr_none
			res 5, a
			ld (#5C3B), a
			ld a, (#5C08)			; LAST_K
			ret
dot_kr_none:
			xor a
			ret

; ---- the entry's data
dot_bsp:		dw 0			; BASIC's SP at entry
dot_hl:			dw 0			; HL at entry: the arguments
dot_bc:			dw 0			; BC at entry: the whole command line
dot_osp:		dw 0			; dot_os: our SP
dot_oix:		dw 0			; dot_os: IX
dot_ch:			db 0			; the character for dot_putc
dot_row:		db 0			; dot_at: row, column (0 based)
dot_col:		db 0
dot_frames:		dw 0			; frames counted (dot_irq, plus FRAMES' advance in the ROM calls): Ticks
dot_fr0:		dw 0			; dot_os: FRAMES at the call's start
dot_iold:		db 0			; BASIC's I register
ntc_cmdbuf:		ds 128			; the arguments, 0 ended (System.CommandLine)
; dot_irq - the IM 2 handler: a frame counted. Only this 8K is touched (it runs with the
; program's memory in the slots and SP on the program's real stack)
dot_irq:
			push hl
			ld hl, (dot_frames)
			inc hl
			ld (dot_frames), hl
			pop hl
			ei
			reti
; the IM 2 vector table, 256-aligned: the Z80 reads its bytes #FF and #100 (the data bus
; gives #FF) - the handler's address; the rest is the entry's two stacks
			ALIGN 256
dot_ivec:
			ds 255 - 48
			ds 32
dot_tstack:						; the entry's own stack (32 bytes: the entry's calls only)
			ds 16
dot_xstack:						; dot_os's own (16 bytes: the slot swap's calls - the Large Model) = dot_ivec + #FF
			dw dot_irq				; the vector

	IFDEF NTC_ZXNDOTL
; ------------------------------------------------------------
; The Large Model (zxndotl): the program runs from #8000 in four 8K pages of
; its own, the Memory class's window #4000-#7FFF is two more, all allocated
; from NextZXOS (IDE_BANK through M_P3DOS) at entry and given back at the end;
; its banks (64K: 8 pages each) come from the same allocator at the Memory
; class's first call (ntc_lib_dot.asm). Slots 2-7 hold ours while the program
; runs, BASIC's while a ROM / esxDOS call runs (dot_os: dotl_bside / dotl_oside).
; The program itself is read from this file, after its first 8K (M_GETHANDLE:
; NextZXOS leaves the file open there), into #8000 on.
; ------------------------------------------------------------
DOTL_MAXPG	equ 6 + 8 * 16			; pages at most: the 6 base ones and 16 banks (1MB)
dotl_bslots:	ds 6			; BASIC's pages in slots 2-7 (NextRegs #52-#57 at entry)
dotl_oslots:	ds 6			; ours (slots 2-3 the window, 4-7 the program #8000-#FFFF), as last seen
dotl_scr:		ds 6			; (dotl_oside's reads)
dotl_npages:	db 0			; pages allocated (in dotl_pages)
dotl_pages:		ds DOTL_MAXPG	; their numbers: the 6 base ones, then the Memory class's 8 a bank
dotl_e:			db 0			; dotl_alloc: the page it got / dotl_free: the page to give back
dotl_hdl:		db 0			; this file's handle
dotl_err:		dw 0			; the message for the error return

; dotl_setup - (the entry, on dot_tstack, BASIC's memory) BASIC's slots noted, the 6
; base pages allocated and mapped, the program read into #8000 on. Doesn't return when
; it fails: the error return to BASIC with a message
dotl_setup:
			ld hl, dotl_bslots		; BASIC's pages in slots 2-7
			ld d, #52
dotl_su_rd:
			ld bc, #243B
			out (c), d
			inc b
			in a, (c)
			ld (hl), a
			inc hl
			inc d
			ld a, d
			cp #58
			jr nz, dotl_su_rd
			ld b, 6					; the 6 base pages
dotl_su_al:
			push bc
			call dotl_page			; one more into dotl_pages
			pop bc
			jr nc, dotl_su_nomem
			djnz dotl_su_al
			ld hl, dotl_pages		; ours: slots 2-3 pages 0, 1 (the window), 4-7 pages 2-5
			ld de, dotl_oslots
			ld bc, 6
			ldir
			call dotl_oside			; mapped (this 8K and the ROM stay: slots 0, 1)
			rst #08
			db #8D					; M_GETHANDLE: A = this file's handle, open after its first 8K
			ld (dotl_hdl), a
			ld hl, #8000
			ld bc, ntc_end - #8000	; the program (the file's end: no window data, no Skip on this platform)
			push bc
			rst #08
			db #9D					; F_READ: A = handle, HL = where, BC = how many
			pop hl
			jr c, dotl_su_short
			or a
			sbc hl, bc				; all of it?
			ret z
dotl_su_short:
			ld hl, dotl_m_short
			jr dotl_fail
dotl_su_nomem:
			ld hl, dotl_m_nomem
; dotl_fail - HL = the message (bit 7 on its last character): the pages back, BASIC's
; memory and stack, the esxDOS custom error return (carry set, A = 0, HL = the message)
dotl_fail:
			ld (dotl_err), hl
			call dotl_freeall
			call dotl_bside
			ld sp, (dot_bsp)
			ld hl, (dotl_err)
			ld iy, #5C3A
			xor a
			scf
			ei
			ret
; dotl_exit - (End: ntc_plat_exit jumps here - this 8K stays mapped when slots 2-7 go
; back to BASIC's; the program's code doesn't) the pages given back, BASIC's memory and
; stack, carry clear (0 OK), interrupts on
dotl_exit:
			ld sp, dot_tstack
			call dotl_freeall
			call dotl_bside
			ld sp, (dot_bsp)
			ld iy, #5C3A
			ld a, (dot_iold)
			ld i, a
			im 1
			or a
			ei
			ret
dotl_m_nomem:	db "Out of memory: no free 8K pages (IDE_BANK", ')' + #80
dotl_m_short:	db "The .DOT file is short: the program did not read in ful", 'l' + #80

; dotl_page - one page allocated (IDE_BANK, on BASIC's side) into dotl_pages: C = its
; number, carry set; carry clear when there is none (or no room in dotl_pages)
dotl_page:
			ld a, (dotl_npages)
			cp DOTL_MAXPG
			ret nc					; (carry clear: full)
			ld hl, dotl_alloc
			call dot_os				; carry set = got one, (dotl_e) = it
			ret nc
			ld hl, dotl_pages
			ld a, (dotl_npages)
			ld e, a
			ld d, 0
			add hl, de
			ld a, (dotl_e)
			ld (hl), a
			ld c, a
			ld a, (dotl_npages)
			inc a
			ld (dotl_npages), a
			scf
			ret
; dotl_freeall - every page in dotl_pages given back (IDE_BANK free, on BASIC's side)
dotl_freeall:
			ld a, (dotl_npages)
			or a
			ret z
			ld b, a
			ld hl, dotl_pages
dotl_fa_lp:
			ld a, (hl)
			ld (dotl_e), a
			push bc
			push hl
			ld hl, dotl_free
			call dot_os
			pop hl
			pop bc
			inc hl
			djnz dotl_fa_lp
			xor a
			ld (dotl_npages), a
			ret

; dotl_bside - slots 2-7 = BASIC's pages, ours noted first (dotl_oslots)
; dotl_oside - slots 2-7 = ours again
; (from code in this 8K, on a stack in it: slots 2-7 change under anything else)
dotl_bside:
			ld hl, dotl_oslots
			ld ix, dotl_bslots
			jr dotl_swap
dotl_oside:
			ld hl, dotl_scr
			ld ix, dotl_oslots
dotl_swap:
			ld d, #52
dotl_sw_lp:
			ld bc, #243B
			out (c), d
			inc b
			in a, (c)				; the page there now
			ld (hl), a
			ld a, (ix + 0)
			out (c), a				; the page to be
			inc hl
			inc ix
			inc d
			ld a, d
			cp #58
			jr nz, dotl_sw_lp
			ret

; ---- BASIC-side (dot_os): the allocator, M_P3DOS's IDE_BANK (#01BD): H = 0 a ZX 8K
; page, L = 1 allocate / 3 free (E = the page), the call's registers in the alternate
; set; carry SET = done, E = the page
dotl_alloc:
			ld hl, #0001
			exx
			ld de, #01BD
			ld c, 7
			rst #08
			db #94					; M_P3DOS
			ld a, e
			ld (dotl_e), a
			ret
dotl_free:
			ld a, (dotl_e)
			ld e, a
			ld hl, #0003
			exx
			ld de, #01BD
			ld c, 7
			rst #08
			db #94
			ret

; ---- esxDOS file calls for a FileSystem class (the Large Model): dot_fs_call runs on BASIC's
; side (HL = dot_fs_call : call dot_os) - NextZXOS pages its own RAM over #C000-#FFFF and reads
; BASIC's system variables during a call, so the call's stack, the name and the data must not be
; in the program's pages: the name goes in dot_fs_name, a stat buffer is dot_fs_stat, file data
; goes through dot_fs_data (256 bytes a call), all in this 8K, which is in both maps.
; In: dot_fs_hook (F_OPEN ...), dot_fs_a, dot_fs_bc, dot_fs_de, dot_fs_hl (HL and IX: NextZXOS
; reads a name's pointer from HL, esxDOS from IX). Out: dot_fs_a, dot_fs_bc, dot_fs_de,
; dot_fs_cy (1 = carry: an error, A its code)
dot_fs_call:
			ld a, (dot_fs_hook)
			ld (dot_fs_hk), a
			ld bc, (dot_fs_bc)
			ld de, (dot_fs_de)
			ld hl, (dot_fs_hl)
			push hl
			pop ix
			ld a, (dot_fs_a)
			rst #08
dot_fs_hk:	db 0
			ld (dot_fs_bc), bc
			ld (dot_fs_de), de
			ld (dot_fs_a), a
			ld a, 0
			rla
			ld (dot_fs_cy), a
			ret
dot_fs_hook:	db 0
dot_fs_a:		db 0
dot_fs_cy:		db 0
dot_fs_bc:		dw 0
dot_fs_de:		dw 0
dot_fs_hl:		dw 0
dot_fs_name:	ds 64
dot_fs_stat:	ds 16
dot_fs_data:	ds 256
	ENDIF

			ASSERT $ <= #4000, "the dot command's entry code and data must fit in #2000-#3FFF"
			ds #4000 - $			; the first 8K of the file, padded
			OPT -Wno-fileorg		; (the file goes on where the 8K ends: the org below is where the program runs, not a gap)
			org #8000			; the program: read into its own pages by the entry

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 40		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 0		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)
NTC_WINHOLE	equ 0		; 1 = the program is built round an Option Reserve range over the window #4000-#7FFF
NTC_WINPAGED	equ 0		; 1 = page 0 code may sit under the window (Option Memory Paged, not Reserved): the Memory class never hands out page 1 (main RAM's own #4000-#7FFF) when the code reaches past #4000
NTC_BUFSIZE	equ 2048		; the library's buffer (ntc_buf: FileSystem, Memory.Copy): Option Buffer
NTC_ISLN	equ 1		; interrupt classes (Option Class Interrupt): the slots ntc_isl has (8 bytes each)
NTC_INTS	equ 1		; 0 = the platform never lets interrupts in (;@ints 0: ntc_xn's safe point has no ei)
NTC_PLATRSV	equ 0		; 1 = the platform's fixed areas (;@reserved) are Reserved in the memory map: the build goes round them (the old top-of-RAM asserts are off)
NTC_CPMGFX	equ 0		; 1 = CP/M: Graphics draws on an Amstrad CPC's screen (2.2: #C000, Plus: block 1 from common memory)

ntc_start:
			di
			ld sp, 0		; the platform's own real stack
			ld (ntc_csp), sp
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:
			dw kw_bssinit, ntc_bss, ntc_bss_size		; the arrays: do they fit, clear them

			; 21: Print "VB test 3"
			dw kw_printstrvar, str0
			dw kw_printnl

			; 22: Chk Red, 0
			dw p_chk_c, lit_0, lit_0

			; 23: Chk Green, 5
			dw p_chk_c, lit_5, lit_5

			; 24: Chk Blue, 6
			dw p_chk_c, lit_6, lit_6

			; 25: Chk Colour.Blue + Size.Large, 16
			dw p_chk_c, lit_16, lit_16

			; 26: c = Green
			dw kw_ltov, 5, var_c

			; 27: Chk c, 5
			dw p_chk_c, var_c, lit_5

			; 29: .w = 3
			dw kw_ltov, 3, var_b_w

			; 30: .h = 4
			dw kw_ltov, 4, var_b_h

			; 31: .label = "box"
			dw kw_strcpy, var_b_label, str1

			; 32: n = .w * .h
			dw kw_mulvv, var_b_w, var_b_h, var_n

			; 34: Chk n, 12
			dw p_chk_c, var_n, lit_12

			; 35: ChkS b.label, "box"
			dw p_chks_c, var_b_label, str1

			; 36: For i = 0 To 2
			dw kw_ztov, var_i
for1_t:

			; 38: .w = i
			dw kw_aset, arr_boxes_w, var_i, var_i

			; 39: .h = i * 2
			dw kw_2x, var_i, tmp1
			dw kw_aset, arr_boxes_h, var_i, tmp1

			; 41: Next
			dw kw_next1l_n, var_i, 2, for1_t
for1_e:

			; 42: Chk boxes(2).w + boxes(2).h, 6
			dw kw_add, arr_boxes_w+4, arr_boxes_h+4, tmp0
			dw p_chk_c, tmp0, lit_6

			; 43: n = 0
			dw kw_ztov, var_n

			; 44: For i = 1 To 3
			dw kw_ltov, 1, var_i
for2_t:

			; 45: On i GoSub one, two, three
			dw kw_cpeqvl, var_i, 1
			dw kw_goto_iffalse_n, on3_0
			dw lbl_one_gs
			dw on3_e_go
on3_0:
			dw kw_cpeqvl, var_i, 2
			dw kw_goto_iffalse_n, on3_1
			dw lbl_two_gs
			dw on3_e_go
on3_1:
			dw kw_cpeqvl, var_i, 3
			dw kw_goto_iffalse_n, on3_2
			dw lbl_three_gs
on3_2:
on3_e:

			; 46: Next
			dw kw_next1l_n, var_i, 3, for2_t
for2_e:

			; 47: Chk n, 321
			dw p_chk_c, var_n, lit_321

			; 48: i = 2
			dw kw_ltov, 2, var_i

			; 49: On i GoTo l1, l2
			dw kw_cpeqvl, var_i, 1
			dw kw_goto_iftrue_n, lbl_l1
			dw kw_cpeqvl, var_i, 2
			dw kw_goto_iftrue_n, lbl_l2

			; 50: Chk 0, 1
			dw p_chk_c, lit_0, lit_1

			; 51: l1:
lbl_l1:

			; 52: Chk 0, 1
			dw p_chk_c, lit_0, lit_1

			; 53: l2:
lbl_l2:

			; 54: Chk 1, 1
			dw p_chk_c, lit_1, lit_1

			; 55: k = Inkey$
			dw kw_inkeys, stmp0
			dw kw_strcpy, var_k, stmp0

			; 56: ChkS k, ""
			dw p_chks_c, var_k, str2

			; 57: Print
			dw kw_printnl

			; 58: Print t; " tests, "; bad; " failed"
			dw kw_printint, var_t
			dw kw_printstrvar, str3
			dw kw_printint, var_bad
			dw kw_printstrvar, str4
			dw kw_printnl

			; 59: End
			dw kw_printnl0
			dw kw_printstrvar, str5
			dw kw_waitkey
			dw kw_stop

			; 60: one:
lbl_one:

			; 61: n = n + 1
			dw kw_inc, var_n

			; 62: Return
			dw lbl_one_rt

			; 63: two:
lbl_two:

			; 64: n = n + 20
			dw kw_addl, var_n, 20, var_n

			; 65: Return
			dw lbl_two_rt

			; 66: three:
lbl_three:

			; 67: n = n + 300
			dw kw_addl, var_n, 300, var_n

			; 68: Return
			dw lbl_three_rt

; ============================================================
; sub chk (normal mode)
; ============================================================

p_chk:

			; 71: t = t + 1
			dw kw_inc, var_t

			; 72: Print t; ":";
			dw kw_printint, var_t
			dw kw_printstrvar, str6

			; 73: If got = want Then Print "ok "; Else Print "FAIL("; got; ") "; : bad = bad + 1
			dw kw_cpeqvv, var_chk_got, var_chk_want
			dw kw_goto_iffalse_n, if5_1
			dw kw_printstrvar, str7
			dw if5_e_go
if5_1:
			dw kw_printstrvar, str8
			dw kw_printint, var_chk_got
			dw kw_printstrvar, str9
			dw kw_inc, var_bad
if5_e:
			dw p_chk_r

; ============================================================
; sub chks (normal mode)
; ============================================================

p_chks:

			; 77: t = t + 1
			dw kw_inc, var_t

			; 78: Print t; ":";
			dw kw_printint, var_t
			dw kw_printstrvar, str6

			; 79: If got = want Then Print "ok "; Else Print "FAIL["; got; "] "; : bad = bad + 1
			dw kw_strcmpeq, var_chks_got, var_chks_want
			dw kw_goto_iffalse_n, if6_1
			dw kw_printstrvar, str7
			dw if6_e_go
if6_1:
			dw kw_printstrvar, str10
			dw kw_printstrvar, var_chks_got
			dw kw_printstrvar, str11
			dw kw_inc, var_bad
if6_e:
			dw p_chks_r

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

on3_e_go:			ld sp, on3_e
			jp ntc_xn
if5_e_go:			ld sp, if5_e
			jp ntc_xn
if6_e_go:			ld sp, if6_e
			jp ntc_xn
lbl_one_gs:			ld (lbl_one_rs), sp
			ld sp, lbl_one
			jp ntc_xn
lbl_one_rt:			ld sp, (lbl_one_rs)
			jp ntc_xn
lbl_two_gs:			ld (lbl_two_rs), sp
			ld sp, lbl_two
			jp ntc_xn
lbl_two_rt:			ld sp, (lbl_two_rs)
			jp ntc_xn
lbl_three_gs:			ld (lbl_three_rs), sp
			ld sp, lbl_three
			jp ntc_xn
lbl_three_rt:			ld sp, (lbl_three_rs)
			jp ntc_xn

p_chk_c:		; call chk (normal)
			pop hl			; got
			ld de, var_chk_got		; (the block of 2 parameters)
			ldi
			ldi
			pop hl			; want
			ldi
			ldi
			ld (p_chk_rs), sp
			ld sp, p_chk
			jp ntc_xn
p_chk_r:		; end of chk
			ld sp, (p_chk_rs)
			jp ntc_xn
p_chks_c:		; call chks (normal)
			pop hl			; got
			ld de, var_chks_got
			ld b, 40
p_chks_si0:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_chks_si0_e
			inc hl
			inc de
			djnz p_chks_si0
			xor a
			ld (de), a
p_chks_si0_e:
			pop hl			; want
			ld de, var_chks_want
			ld b, 40
p_chks_si1:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_chks_si1_e
			inc hl
			inc de
			djnz p_chks_si1
			xor a
			ld (de), a
p_chks_si1_e:
			ld (p_chks_rs), sp
			ld sp, p_chks
			jp ntc_xn
p_chks_r:		; end of chks
			ld sp, (p_chks_rs)
			jp ntc_xn

; ============================================================
; Variables
; ============================================================

var_c:			dw 0
var_b_w:			dw 0
var_b_h:			dw 0
			db 40			; capacity
var_b_label:			ds 41
var_n:			dw 0
var_i:			dw 0
			db 40			; capacity
var_k:			ds 41
var_t:			dw 0
var_bad:			dw 0
p_chk_rs:			dw 0
var_chk_got:			dw 0, 0		; parameters, one block
var_chk_want		equ var_chk_got + 2
p_chks_rs:			dw 0
			db 40			; capacity
var_chks_got:			ds 41
			db 40			; capacity
var_chks_want:			ds 41
lbl_one_rs:			dw 0
lbl_two_rs:			dw 0
lbl_three_rs:			dw 0
tmp0:			dw 0
tmp1:			dw 0
			db 40			; capacity
stmp0:			ds 41

; numbers passed by address (read only)
lit_0:			dw 0
lit_5:			dw 5
lit_6:			dw 6
lit_16:			dw 16
lit_12:			dw 12
lit_321:			dw 321
lit_1:			dw 1

; ============================================================
; Strings
; ============================================================

str0:			db "VB test 3", 0
str1:			db "box", 0
str2:			db 0
str3:			db " tests, ", 0
str4:			db " failed", 0
str5:			db "Press a key", 0
str6:			db ":", 0
str7:			db "ok ", 0
str8:			db "FAIL(", 0
str9:			db ") ", 0
str10:			db "FAIL[", 0
str11:			db "] ", 0

; ============================================================
; Keyword library (used)
; ============================================================

;## ntc_data @shared ntc_d_nmode
; ------------------------------------------------------------
; Scratch space: the core every program has (with ntc_d_nmode). The rest of
; the run time's variables are @data sections, each linked only when a
; linked section's code names one of its labels (no header lists them).
; They stay in this order: the keyword ROM's registry keeps each variable's
; address (a Library: ROM program has them as fixed addresses)
; ------------------------------------------------------------
ntc_next:		ret				; IX target that continues the thread
ntc_csp:		dw 0			; caller SP, for kw_stop (and the normal mode stack)
ntc_ip:			dw 0			; normal mode: thread position while out of the thread

;## ntc_d_nmode @data
ntc_nmode:		db 0			; 1 = running in normal mode (waits let interrupts in)

;## ntc_d_lead @data
ntc_lead:		db 0			; printint: digit seen

;## ntc_d_sptr @data
ntc_sptr:		dw 0			; printbuf: text pointer

;## ntc_d_ivar @data
ntc_ivar:		dw 0			; inputint / inkey: dest var

;## ntc_d_numbuf @data
ntc_numbuf:		ds 14			; printint / long print: digits (+ spaces for Option VBPrint)

;## kw_stop ntc_data ntc_plat_exit @shared
kw_stop:
			ld ix, ntc_stop_back
			jp ntc_plat_exit
ntc_stop_back:
			ld sp, (ntc_csp)
			ei
			ret

;## kw_waitkey ntc_data ntc_plat_key
; kw_waitkey - wait for a key (Option PressAnyKeyOnEnd, before kw_stop)
kw_waitkey:
			ld ix, ntc_next
			jp ntc_plat_getkey

;## ntc_xn ntc_data @shared
; normal mode "next": every normal mode keyword ends here (its ret
; became jp ntc_xn). Thread position to ntc_ip, real stack, one
; instruction with interrupts on, then back into the thread.
ntc_xn:
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
	IF NTC_INTS					; (;@ints 0: a platform that never lets interrupts in - the Next's dot commands)
			ei
			nop					; an interrupt can be taken here
			di
	ENDIF
			ld sp, (ntc_ip)
			ret

;## kw_goto_iffalse (normal mode copy)
;kw_goto_iffalse, <label>  - branch if NZ (false)
kw_goto_iffalse_n:
			pop hl
			jp z, ntc_xn
			ld sp, hl
			jp ntc_xn

;## kw_goto_iftrue (normal mode copy)
;kw_goto_iftrue, <label>  - branch if Z (true)
kw_goto_iftrue_n:
			pop hl
			jp nz, ntc_xn
			ld sp, hl
			jp ntc_xn

;## ntc_for_jump (normal mode copy)
; tails for the FOR / NEXT keywords. DE = var value, HL = limit,
; SP = thread at the label word. Signed compare by flipping bit 15.
; ntc_for_gt: jump to the label if var > limit, else skip it
ntc_for_gt_n:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			or a
			sbc hl, de			; limit - var, carry = var > limit
			pop hl
			jp nc, ntc_xn
			ld sp, hl
			jp ntc_xn
; ntc_for_lt: jump to the label if var < limit, else skip it
ntc_for_lt_n:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			ex de, hl
			or a
			sbc hl, de			; var - limit, carry = var < limit
			pop hl
			jp nc, ntc_xn
			ld sp, hl
			jp ntc_xn
; ntc_for_le: jump to the label if var <= limit (loop again). A not 0: the
; step took var past 32767 (or -32768): the loop ends (ntc_for_ge too)
ntc_for_le_n:
			or a
			jr nz, ntc_for_end_n
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			or a
			sbc hl, de			; limit - var, no carry = var <= limit
			pop hl
			jp c, ntc_xn
			ld sp, hl
			jp ntc_xn
; ntc_for_ge: jump to the label if var >= limit (loop again)
ntc_for_ge_n:
			or a
			jr nz, ntc_for_end_n
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			ex de, hl
			or a
			sbc hl, de			; var - limit, no carry = var >= limit
			pop hl
			jp c, ntc_xn
			ld sp, hl
			jp ntc_xn
ntc_for_end_n:
			pop hl
			jp ntc_xn

;## kw_next1l (normal mode copy) ntc_for_jump
;kw_next1l, <var>, <literal limit>, <toplabel>
;  NEXT for STEP 1: inc var, back to the top while var <= limit
kw_next1l_n:
			pop hl
			inc (hl)
			ld e, (hl)
			inc hl
			jr nz, ntc_n1l_nc_n
			inc (hl)
ntc_n1l_nc_n:
			ld d, (hl)
			pop hl
			ld a, d					; A = #FF when it went past 32767 (#8000)
			xor #80
			or e
			sub 1
			sbc a, a
			jp ntc_for_le_n

;## kw_ltov
;kw_ltov, <literal>, <destvar>
kw_ltov:
			pop de
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_ztov
;kw_ztov, <destvar>
kw_ztov:
			xor a
			pop hl
			ld (hl), a
			inc hl
			ld (hl), a
			ret

;## kw_inc
;kw_inc, <var>
kw_inc:
			pop hl
			inc (hl)
			ret nz
			inc hl
			inc (hl)
			ret

;## kw_add
;kw_add, <var1>, <var2>, <destvar>
kw_add:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			add hl, de
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_addl
;kw_addl, <var>, <literal>, <destvar>
kw_addl:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			add hl, de
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_2x
;kw_2x, <var>, <destvar>
kw_2x:
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			add hl, hl
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## ntc_mul
; BC * DE -> pop destvar, store. Low 16 bits (same signed/unsigned)
ntc_mul:
			ld hl, 0
			ld a, 16
ntc_mul_loop:
			add hl, hl
			sla e
			rl d
			jr nc, ntc_mul_skip
			add hl, bc
ntc_mul_skip:
			dec a
			jr nz, ntc_mul_loop
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_mulvv ntc_mul
;kw_mulvv, <var1>, <var2>, <destvar>
kw_mulvv:
			pop hl
			ld c, (hl)
			inc hl
			ld b, (hl)
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			jp ntc_mul

;## ntc_cmp
ntc_cmp_slt:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ult:
			ex de, hl
			or a
			sbc hl, de
			sbc a, a
			inc a
			ret
ntc_cmp_sge:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_uge:
			ex de, hl
			or a
			sbc hl, de
			sbc a, a
			ret
ntc_cmp_sgt:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ugt:
			or a
			sbc hl, de
			sbc a, a
			inc a
			ret
ntc_cmp_sle:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ule:
			or a
			sbc hl, de
			sbc a, a
			ret
ntc_cmp_eq:
			or a
			sbc hl, de
			ret
ntc_cmp_ne:
			or a
			sbc hl, de
			jr z, ntc_cmp_ne_f
			xor a
			ret
ntc_cmp_ne_f:
			or 1
			ret

;## kw_cpeqvv ntc_cmp
;kw_cpeqvv, <var1>, <var2>
kw_cpeqvv:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			jp ntc_cmp_eq

;## kw_cpeqvl ntc_cmp
kw_cpeqvl:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			jp ntc_cmp_eq

;## kw_aset
;kw_aset, <arraybase>, <indexvar>, <sourcevar>
kw_aset:
			pop de
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			add hl, hl
			add hl, de
			ex de, hl
			pop hl
			ld c, (hl)
			inc hl
			ld b, (hl)
			ex de, hl
			ld (hl), c
			inc hl
			ld (hl), b
			ret

;## kw_strcpy
;kw_strcpy, <destaddr>, <srcaddr>  - cut at the destination's capacity byte
kw_strcpy:
			pop de
			pop hl
			dec de
			ld a, (de)
			ld b, a
			inc de
ntc_strcpy_loop:
			ld a, (hl)
			ld (de), a
			or a
			ret z
			inc hl
			inc de
			djnz ntc_strcpy_loop
			xor a
			ld (de), a
			ret

;## kw_strcmpeq
;kw_strcmpeq, <addr1>, <addr2>  - Z if equal
kw_strcmpeq:
			pop de
			pop hl
ntc_streq_loop:
			ld a, (de)
			cp (hl)
			ret nz
			or a
			ret z
			inc hl
			inc de
			jr ntc_streq_loop

;## ntc_printbuf ntc_data ntc_plat_screen
; print the 0 terminated ASCII text at (ntc_sptr), then ret (thread)
ntc_printbuf:
			ld hl, (ntc_sptr)
			ld a, (hl)
			or a
			ret z
			inc hl
			ld (ntc_sptr), hl
			ld ix, ntc_printbuf
			jp ntc_plat_putc

;## kw_printstrvar ntc_printbuf
;kw_printstrvar, <straddr>
kw_printstrvar:
			pop hl
			ld (ntc_sptr), hl
			jp ntc_printbuf

;## ntc_itoa ntc_data
; HL = signed value, DE = buffer: writes the digits and a 0 (DE ends on
; the 0). jp (ix) back. Uses A, BC, IY.
ntc_itoa:
			bit 7, h
			jr z, ntc_ia_pos
			ld a, '-'
			ld (de), a
			inc de
			xor a
			sub l
			ld l, a
			sbc a, a
			sub h
			ld h, a
ntc_ia_pos:
			xor a
			ld (ntc_lead), a
			ld iy, ntc_pow10
ntc_ia_pow:
			ld c, (iy+0)
			ld b, (iy+1)
			ld a, b
			or c
			jr z, ntc_ia_last
			ld a, '0' - 1
ntc_ia_sub:
			inc a
			and a
			sbc hl, bc
			jr nc, ntc_ia_sub
			add hl, bc
			cp '0'
			jr nz, ntc_ia_out
			ld b, a
			ld a, (ntc_lead)
			or a
			ld a, b
			jr z, ntc_ia_skip
ntc_ia_out:
			ld (de), a
			inc de
			ld a, 1
			ld (ntc_lead), a
ntc_ia_skip:
			inc iy
			inc iy
			jr ntc_ia_pow
ntc_ia_last:
			ld a, l
			add a, '0'
			ld (de), a
			inc de
			xor a
			ld (de), a
			jp (ix)
ntc_pow10:		dw 10000, 1000, 100, 10, 0

;## kw_printint ntc_printbuf ntc_itoa
;kw_printint, <var>  - signed decimal
kw_printint:
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			ld de, ntc_numbuf
			ld ix, ntc_pi_done
			jp ntc_itoa
ntc_pi_done:
			ld hl, ntc_numbuf
			ld (ntc_sptr), hl
			jp ntc_printbuf

;## kw_printnl0 ntc_data ntc_plat_screen
;kw_printnl0  - new line unless the cursor is at the start of a line
kw_printnl0:
			ld a, (ntc_curx)
			or a
			ret z
			ld ix, ntc_next
			jp ntc_plat_newline

;## kw_printnl ntc_data ntc_plat_screen
;kw_printnl
kw_printnl:
			ld ix, ntc_next
			jp ntc_plat_newline

;## kw_inkeys ntc_data ntc_plat_key
;kw_inkeys, <dest>  - Inkey$: the new key press as a string, "" if none
kw_inkeys:
			pop hl
			ld (ntc_ivar), hl
			ld ix, ntc_inks_got
			jp ntc_plat_scankey
ntc_inks_got:
			ld hl, (ntc_ivar)
			ld (hl), a
			or a
			ret z
			inc hl
			ld (hl), 0
			ret

;## kw_bssinit ntc_data ntc_plat_memtop ntc_plat_screen kw_stop @shared
;kw_bssinit, <start>, <size>  - the start of the main thread: the program's arrays live after
;  it (from ntc_end, not in its file). Check they fit under the platform's top (and 256 bytes
;  under the real stack when that is above them), then clear them. Too big: a message, the
;  program stops.
kw_bssinit:
			pop hl
			ld (ntc_bsa), hl
			pop bc
			ld (ntc_bsz), bc
			ld (ntc_bsp), sp
			ld sp, (ntc_csp)
			add hl, bc				; HL = their end
			ex de, hl
			call ntc_plat_memtop	; HL = the platform's top
			or a
			sbc hl, de
			jr c, ntc_bs_big
			ld hl, (ntc_csp)		; the real stack, when above them
			ld bc, (ntc_bsa)
			or a
			sbc hl, bc
			jr c, ntc_bs_ok
			jr z, ntc_bs_ok		; (the stack just under them: CP/M's ntc_cpmstack = their start)
			ld hl, (ntc_csp)
			ld bc, -256
			add hl, bc
			or a
			sbc hl, de
			jr c, ntc_bs_big
ntc_bs_ok:
			ld bc, (ntc_bsz)
			ld a, b
			or c
			jr z, ntc_bs_done
			ld hl, (ntc_bsa)
			ld (hl), 0
			dec bc
			ld a, b
			or c
			jr z, ntc_bs_done
			ld d, h
			ld e, l
			inc de
			ldir
ntc_bs_done:
			ld sp, (ntc_bsp)
			ret
ntc_bs_big:
			ld hl, ntc_bstxt
ntc_bs_pl:
			ld a, (hl)
			or a
			jr z, ntc_bs_stop
			inc hl
			ld (ntc_bsa), hl
			ld ix, ntc_bs_pn
			jp ntc_plat_putc
ntc_bs_pn:
			ld hl, (ntc_bsa)
			jr ntc_bs_pl
ntc_bs_stop:
			ld ix, kw_stop
			jp ntc_plat_newline
ntc_bsa:		dw 0
ntc_bsz:		dw 0
ntc_bsp:		dw 0
ntc_bstxt:		db "GURU 001", 0

;## ntc_plat_exit
; ntc_plat_exit - back to BASIC: the pages given back, its memory in slots 2-7, its
; stack, carry clear (0 OK), interrupts on - dotl_exit, in the entry's 8K
ntc_plat_exit:
			jp dotl_exit			; (in the entry's 8K: the program's own pages are unmapped on the way)

;## ntc_plat_memtop
; ntc_plat_memtop - HL = the first byte the Memory class's Small heap must not use:
; #FF80, under the real stack (128 bytes from #FFFF down). Called on the real stack
; (call / ret), only by the Memory class
ntc_plat_memtop:
			ld hl, #FF80
			ret

; ============================================================
; NTC Platform - ZX Spectrum Next, a dot command: the Small Model
; (c) 2026 Cyborg Unicorn Pty Ltd - MIT License
; ============================================================
; No call, no push: SP stays in the thread. Every routine is
; entered with jp, return address in IX, and ends with jp (ix).
;
; A NextZXOS / esxDOS dot command: NAME.DOT in C:/DOT, typed as .name args
; at the BASIC prompt. NextZXOS loads the file at #2000 into DivMMC's 8K
; page and calls it with HL = the arguments (0: none), BC = the whole line,
; SP = BASIC's stack; it returns with ret, carry clear (0 OK), or carry set
; and A = an esxDOS error, or A = 0 and HL = its own message (bit 7 on the
; last character). The BASIC program, its variables and its screen are kept
; as found: this is a utility that runs and comes back, not a program that
; owns the machine (that is the zxn platform: a NEX file).
;
; Memory  the 8K at #2000-#3FFF, and nothing else: the code, its data, the
;         arrays (ntc_free must end by #4000: the assembly says so when not),
;         the real stack (dot_stack, 128 bytes in the data). Option Memory
;         Small: the heap is what is left up to #4000 (ntc_plat_memtop). The
;         Large Model (zxndotl, built on this one) has 32K and banks.
;           #0000-#1FFF  DivMMC's ROM (esxDOS: rst 8 the file calls, rst #10 /
;                        rst #18 the 48K ROM's print and routines)
;           #2000-#3FFF  this dot command
;           #4000-#FFFF  BASIC's: the screen, the system variables, its
;                        program and stack - not touched
; Console text goes to BASIC's screen through the 48K ROM's rst #10 (the
;         current channel: the upper screen, opened at the start), so it
;         prints as every dot command does - in the mode BASIC is in, scrolling,
;         "scroll?" and all. Cls is the ROM's CLS, Locate the AT control code
;         (22, row, column), Mode does nothing. 32 columns, 24 rows are
;         counted (the ROM wraps and scrolls itself). Keys come from the ROM's
;         keyboard scan (LAST_K, set by its interrupt): Enter 13, Delete 127,
;         the cursor keys the CPC firmware's codes (up 240, down 241, left 242,
;         right 243), as the zxn platform gives them.
; The ROM  (the sections that switch to the real stack for dot_os are @shared: one
;         copy, no normal mode rewrite of their SP loads - as cpm's ntc_bdos)
;         a ROM routine (rst #10, rst #18, M_P3DOS) pages DivMMC out while
;         it runs, so this 8K is not there then: such a call runs on BASIC's
;         stack (SP as the command was entered) through dot_os, with IY the
;         ROM's (ERR_NR, #5C3A), IM 1 and interrupts on for the ROM's keyboard
;         and "scroll?".
; Interrupts  while the program runs the Z80 is in IM 2 with a vector and a
;         handler of its own in this 8K (dot_irq: it counts dot_frames), so the
;         ROM's handler at #0038 - which would page DivMMC out under a stack in
;         this 8K, or run over nothing of BASIC's with the Large Model's pages in
;         the slots - never runs then. Normal mode's safe points let interrupts in
;         as on every platform (the handler only touches this 8K). The vector
;         table is 257 bytes of which only the last two are read (the data bus
;         gives #FF): the rest holds the entry's two small stacks.
; Frame   waits for the next interrupt (dot_frames moving on); Ticks is
;         dot_frames: the frames counted here, plus FRAMES' advance during the
;         ROM calls (dot_os adds it), 50 a second.
; Command line  System.CommandLine: the arguments, copied at entry into
;         ntc_cmdbuf (up to 127 characters), ended at #0D, ':' (outside
;         quotes) or 0 - before anything can move BASIC's line.
; End     ntc_plat_exit: SP back, carry clear, ei, ret - the BASIC prompt
;         prints 0 OK and the program is as it was.
; Files   none yet (the FileSystem class is not on this platform; esxDOS's
;         F_OPEN / F_READ ... through rst 8 are the way, later).
; ============================================================
;@text     byte
;@scrinit  0
;@irq      0
;@cols     32
;@rows     24
;@dotfile  1
; ============================================================

;## ntc_plat_data
ntc_curx:		db 0			; column (0 based) - counted for Tab
ntc_cury:		db 0			; row (0 based)
ntc_scols:		db 32			; columns
ntc_smode:		db 1			; screen mode (nothing here: 32 columns)
			ds 128
dot_stack:						; the program's real stack (;@stack): 128 bytes, in the 8K

;## ntc_plat_screen ntc_plat_data ntc_data @shared
; ntc_plat_putc - A = character: rst #10 on BASIC's side, the column counted (the
; ROM wraps at the edge: so does the count)
ntc_plat_putc:
			ld (dot_ch), a
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ld hl, dot_putc
			call dot_os
			ld sp, (ntc_ip)
			ld a, (ntc_scols)
			ld b, a
			ld a, (ntc_curx)
			inc a
			cp b
			jr c, ntc_pc_col
			xor a					; wrapped: the ROM moved to the next row
			ld hl, ntc_cury
			inc (hl)
ntc_pc_col:
			ld (ntc_curx), a
			jp (ix)

; ntc_plat_newline - 13 (the ROM's new line)
ntc_plat_newline:
			ld a, 13
			ld (dot_ch), a
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ld hl, dot_putc
			call dot_os
			ld sp, (ntc_ip)
			xor a
			ld (ntc_curx), a
			ld a, (ntc_cury)
			inc a
			cp 24
			jr c, ntc_nl_row
			ld a, 23				; (the ROM scrolls)
ntc_nl_row:
			ld (ntc_cury), a
			jp (ix)

;## ntc_plat_key ntc_data @shared
; ntc_plat_scankey - A = key or 0: the ROM's LAST_K after a frame (its interrupt
; scans the keyboard), the ROM's codes made the platform's: Enter 13, Delete (12)
; 127, the cursor keys (8-11) 242, 243, 241, 240; other control codes 0
ntc_plat_scankey:
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ld hl, dot_kread
			call dot_os
			ld sp, (ntc_ip)
			cp 32
			jr nc, ntc_sk_done		; a character
			cp 13
			jr z, ntc_sk_done
			cp 12
			jr nz, ntc_sk_cur
			ld a, 127				; Delete
			jr ntc_sk_done
ntc_sk_cur:
			cp 8
			jr c, ntc_sk_none
			cp 12
			jr nc, ntc_sk_none
			ld hl, ntc_sk_tab - 8
			add a, l
			ld l, a
			jr nc, ntc_sk_rd
			inc h
ntc_sk_rd:
			ld a, (hl)
			jr ntc_sk_done
ntc_sk_none:
			xor a
ntc_sk_done:
			jp (ix)
ntc_sk_tab:		db 242, 243, 241, 240	; left, right, down, up

; ntc_plat_getkey - wait for a key
ntc_plat_getkey:
			ld (ntc_gklink), ix
ntc_gk_poll:
			ld ix, ntc_gk_back
			jp ntc_plat_scankey
ntc_gk_back:
			or a
			jr z, ntc_gk_poll
			ld ix, (ntc_gklink)
			jp (ix)
ntc_gklink:		dw 0


ntc_end:				; the end of the program (and of its file)
			DISPLAY "NTC memory: program ", /H, ntc_start, "-", /H, ntc_end - 1, " arrays ", /H, ntc_bss, "-", /H, ntc_free - 1, " stack 0 down (the platform's)"
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bssfrom	equ ntc_end
ntc_bss		equ ntc_bssfrom
arr_boxes		equ ntc_bss + 0		; 6 bytes
arr_boxes_w		equ ntc_bss + 6		; 6 bytes
arr_boxes_h		equ ntc_bss + 12		; 6 bytes
ntc_bss_size	equ 18
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
ntc_memtab	equ ntc_free		; the Memory class's tables
			ASSERT ntc_free <= #FF80, "zxndotl: the program and its arrays must end by #FF80 (the 32K at #8000, less the stack)"
